local function ShowDialog(settings)
    if UI.activeMenu then UI.activeMenu:Hide() end
    local name = settings.dialogName
    local frame = name and namedDialogs[name] or (not name and UI.selectionDialog)
    if not frame then
        frame = CreateSelectionDialog(name)
        if name then namedDialogs[name] = frame else UI.selectionDialog = frame end
    end
    -- Replacing an open prompt resolves its previous cancellation callback first.
    frame:Hide()
    frame.dialogGeneration = (frame.dialogGeneration or 0) + 1
    frame.title:SetText(settings.title or "APR")
    APR:SetFontStringRole(frame.title, "accent")
    frame.description:SetText(settings.description or "")
    frame.confirming = settings.confirmation == true
    frame.confirmationDetails = settings.details ~= nil
    frame.comparison = settings.comparison ~= nil
    frame.options, frame.onSelect = settings.comparison or settings.details or settings.options or {}, settings.onSelect
    frame.acceptButton:SetText(settings.acceptText or ACCEPT)
    frame.cancelButton:SetText(settings.cancelText or CANCEL)
    frame.onAccept, frame.onCancel = settings.onAccept, settings.onCancel
    frame:Layout()
    frame:ClearAllPoints()
    local owner = settings.owner
    frame:SetPoint("CENTER", owner and owner:IsShown() and owner or UIParent, "CENTER")
    frame:SetFrameStrata("FULLSCREEN_DIALOG")
    frame:Show()
    frame.list:RefreshVisible(true)
    return frame
end--[[APR_DIAG]]
