function UI:ShowSelectionDialog(title, description, options, onSelect, onCancel, owner)
    return ShowDialog({
        title = title,
        description = description,
        options = options,
        onSelect = onSelect,
        onCancel = onCancel,
        owner = owner,
    })
end--[[APR_DIAG]]
