function UI:ShowConfirmationDialog(text, onAccept, onCancel, owner)
    if type(text) == "table" then
        return ShowDialog({
            dialogName = text.dialogName,
            title = text.title,
            description = text.description,
            details = text.details,
            comparison = text.comparison,
            acceptText = text.acceptText,
            cancelText = text.cancelText,
            onAccept = onAccept,
            onCancel = onCancel,
            owner = owner,
            confirmation = true,
        })
    end
    local title, description = (text or ""):match("^(.-)\n\n(.+)$")
    return ShowDialog({
        title = title or text,
        description = description,
        onAccept = onAccept,
        onCancel = onCancel,
        owner = owner,
        confirmation = true,
    })
end--[[APR_DIAG]]
UI.ShowConfirmationDialog =
    APRTrace("APR-Core/ui/foundations/SelectionDialog.lua:250:UI:ShowConfirmationDialog#24", UI.ShowConfirmationDialog)--[[/APR_DIAG]]
